// Picked up by the goto reader together with their dependencies. The generated
// model entry points are appended only when the Python frontend is enabled.
static std::vector<std::string> make_python_c_models()
{
  std::vector<std::string> models = python_c_extern_deps;
#ifdef ENABLE_PYTHON_FRONTEND
  models.insert(
    models.end(),
    std::begin(python_c_models_generated),
    std::end(python_c_models_generated));
#endif
  return models;
}
const static std::vector<std::string> python_c_models = make_python_c_models();

